using namespace std;
​
// 明文长度和密码本尺寸
static int plaintextLength, cipherSize;
// 密码本（二维矩阵）
vector<vector<int>> cipherBook;
// 方向数组（右、下、上、左）
vector<vector<int>> directions = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
// 记录字典序最小的加密路径
string minCipherPath;
// 是否找到有效路径
bool found = false;
​
// 深度优先搜索，尝试找到所有可能的加密路径
void dfs(const vector<int>& plaintext, int index, int x, int y, vector<vector<bool>>& visited, vector<string>& path);
​
int main() {
    cin >> plaintextLength;
    vector<int> plaintext(plaintextLength);
    for (int& num : plaintext) {
        cin >> num;
    }
​
    cin >> cipherSize;
    cipherBook.resize(cipherSize, vector<int>(cipherSize));
    for (auto& row : cipherBook) {
        for (int& num : row) {
            cin >> num;
        }
    }
​
    vector<vector<bool>> visited(cipherSize, vector<bool>(cipherSize, false));
​
    // 遍历密码本，寻找明文的起始数字
    for (int i = 0; i < cipherSize; ++i) {
        for (int j = 0; j < cipherSize; ++j) {
            if (cipherBook[i][j] == plaintext[0]) {
                vector<string> path;
                dfs(plaintext, 0, i, j, visited, path);
            }
        }
    }
​
    cout << (found ? minCipherPath : "error") << endl;
    return 0;
}
​
void dfs(const vector<int>& plaintext, int index, int x, int y, vector<vector<bool>>& visited, vector<string>& path) {
    if (index == plaintextLength) {
        // 生成当前路径的字符串表示
        string currentPath = "";
        for (const string& step : path) {
            currentPath += step + " ";
        }
        if (!found || currentPath < minCipherPath) {
            minCipherPath = currentPath;
        }
        found = true;
        return;
    }
​
    // 边界检查、是否访问过、是否匹配当前明文字符
    if (x < 0 || y < 0 || x >= cipherSize || y >= cipherSize || visited[x][y] || cipherBook[x][y] != plaintext[index]) {
        return;
    }
​
    visited[x][y] = true;
    path.push_back(to_string(x) + " " + to_string(y));
​
    for (const auto& dir : directions) {
        dfs(plaintext, index + 1, x + dir[0], y + dir[1], visited, path);
    }
​
    visited[x][y] = false;
    path.pop_back(); // 回溯删除最后添加的坐标
}
