public class Main {
    // 明文长度和密码本尺寸
    static int plaintextLength, cipherSize;
    static int[][] cipherBook;
    static final int[][] directions = {{0, 1}, {1, 0}, {-1, 0}, {0, -1}};
    // 记录字典序最小的加密路径
    static String minCipherPath = "";
    // 是否找到有效路径
    static boolean found = false;
​
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
​
        plaintextLength = scanner.nextInt();
        int[] plaintext = new int[plaintextLength];
        for (int i = 0; i < plaintextLength; i++) {
            plaintext[i] = scanner.nextInt();
        }
​
        cipherSize = scanner.nextInt();
        cipherBook = new int[cipherSize][cipherSize];
        for (int i = 0; i < cipherSize; i++) {
            for (int j = 0; j < cipherSize; j++) {
                cipherBook[i][j] = scanner.nextInt();
            }
        }
​
        boolean[][] visited = new boolean[cipherSize][cipherSize];
​
        // 遍历密码本，寻找明文的起始数字
        for (int i = 0; i < cipherSize; i++) {
            for (int j = 0; j < cipherSize; j++) {
                // 找到起始点开始进行递归寻找
                if (cipherBook[i][j] == plaintext[0]) {
                    List<String> path = new ArrayList<>();
                    dfs(plaintext, 0, i, j, visited, path);
                }
            }
        }
​
        System.out.println(found ? minCipherPath.trim() : "error");
    }
​
    private static void dfs(int[] plaintext, int index, int x, int y, boolean[][] visited, List<String> path) {
        if (index == plaintextLength) {
            String currentPath = String.join(" ", path);
            if (!found || currentPath.compareTo(minCipherPath) < 0) {
                minCipherPath = currentPath;
            }
            found = true;
            return;
        }
         // 边界检查、是否访问过、是否匹配当前明文字符
        if (x < 0 || y < 0 || x >= cipherSize || y >= cipherSize || visited[x][y] || cipherBook[x][y] != plaintext[index]) {
            return;
        }
​
        visited[x][y] = true;
        path.add(x + " " + y);
        // 递归 
        for (int[] dir : directions) {
            dfs(plaintext, index + 1, x + dir[0], y + dir[1], visited, path);
        }
​
        visited[x][y] = false;
        path.remove(path.size() - 1); // 回溯
    }
}
