package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
    "strconv"
)
​
var (
    // 明文长度
    plaintextLength int
    // 密码本规格
    cipherSize int
    // 存储密码本内容
    cipherBook [][]int
    directions = [][2]int{{0, 1}, {1, 0}, {-1, 0}, {0, -1}}
    // 记录字典序最小的加密路径
    minCipherPath string
    // 是否找到有效路径
    found bool
)
​
func dfs(plaintext []int, index, x, y int, visited [][]bool, path []string) {
    if index == plaintextLength {
        currentPath := strings.Join(path, " ")
        if !found || currentPath < minCipherPath {
            minCipherPath = currentPath
        }
        found = true
        return
    }
    //  边界检查、是否访问过、是否匹配当前明文字符
    if x < 0 || y < 0 || x >= cipherSize || y >= cipherSize || visited[x][y] || cipherBook[x][y] != plaintext[index] {
        return
    }
​
    visited[x][y] = true
    path = append(path, fmt.Sprintf("%d %d", x, y))
​
    for _, dir := range directions {
        dfs(plaintext, index+1, x+dir[0], y+dir[1], visited, path)
    }
​
    visited[x][y] = false
}
​
func main() {
    scanner := bufio.NewScanner(os.Stdin)
​
    scanner.Scan()
    fmt.Sscan(scanner.Text(), &plaintextLength)
​
    scanner.Scan()
    plaintext := []int{}
    for _, v := range strings.Fields(scanner.Text()) {
        num, _ := strconv.Atoi(v)
        plaintext = append(plaintext, num)
    }
​
    scanner.Scan()
    fmt.Sscan(scanner.Text(), &cipherSize)
​
    cipherBook = make([][]int, cipherSize)
    visited := make([][]bool, cipherSize)
    for i := range cipherBook {
        scanner.Scan()
        cipherBook[i] = make([]int, cipherSize)
        visited[i] = make([]bool, cipherSize)
        for j, v := range strings.Fields(scanner.Text()) {
            cipherBook[i][j], _ = strconv.Atoi(v)
        }
    }
​
    for i := 0; i < cipherSize; i++ {
        for j := 0; j < cipherSize; j++ {
            if cipherBook[i][j] == plaintext[0] {
                dfs(plaintext, 0, i, j, visited, []string{})
            }
        }
    }
​
    if found {
        fmt.Println(minCipherPath)
    } else {
        fmt.Println("error")
    }
}
